INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('eb8aee67-2e05-56e8-818f-bdbfeb8ade8d', 'Malaysia Green Economy Guideline Manual, Tourism', 'Green Economy Guideline Manual, Tourism', 'These Green Economy guidelines (GEG) manual provide a checklist for businesses to address areas of procurement, operations and supply chain management in order to minimize impact on the environment.', 'These Green Economy guidelines (GEG) manual provide a checklist for businesses to address areas of procurement, operations and supply chain management in order to minimize impact on the environment.', 'These Green Economy guidelines (GEG) manual provide a checklist for businesses to address areas of procurement, operations and supply chain management in order to minimize impact on the environment.', 'Malaysia', 'circularity', 'in_force', '2014-01-01'::date, 'Malaysia', 'https://www.carrotsandsticks.org/policies/109_40', ARRAY['guidance_frameworks', 'malaysia', 'sdg12', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
