INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('41ca3d53-4619-54b8-a184-2d78171196bf', 'Malaysia Act 265 Employment Act', 'Act 265 Employment Act 1955', 'The Act 265 Employment Act 1955 in Malaysia, last updated in 2012, regulates various aspects of employment contracts, wages, deductions, payment systems, maternity protection, employment of women, children, and foreign employees, termination benefits, and procedures for complaints and inquiries. It also covers sexual harassment in the workplace. The Act aims to ensure fair labor practices, protect employees'' rights, and establish guidelines for employers in Malaysia.', 'The Act 265 Employment Act 1955 in Malaysia, last updated in 2012, regulates various aspects of employment contracts, wages, deductions, payment systems, maternity protection, employment of women, children, and foreign employees, termination benefits, and procedures for complaints and inquiries. It also covers sexual harassment in the workplace. The Act aims to ensure fair labor practices, protect employees'' rights, and establish guidelines for employers in Malaysia.', 'The Act 265 Employment Act 1955 in Malaysia, last updated in 2012, regulates various aspects of employment contracts, wages, deductions, payment systems, maternity protection, employment of women, children, and foreign employees, termination benefits, and procedures for complaints and inquiries. It also covers sexual harassment in the workplace. The Act aims to ensure fair labor practices, protect employees'' rights, and establish guidelines for employers in Malaysia.', 'Malaysia', 'social', 'in_force', '2012-01-01'::date, 'Malaysia', 'https://www.carrotsandsticks.org/policies/109_1', ARRAY['sdg8', 'other sustainability policy', 'malaysia', 'regulations', 'mandatory', 'sdg5']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f8a547a2-16bf-58e1-9a1f-9f8500f26db4', 'Malaysian Code on Corporate Governance (Revised', 'Malaysian Code on Corporate Governance (Revised 2007)', 'The Malaysian Code on Corporate Governance as revised in 2007 represents the continued collaborative efforts between Government and the industry. Key amendments shown in this Code are aimed at strengthening the board of directors and audit committees, and ensuring that the board of directors and audit committees discharge their roles and responsibilities effectively.', 'The Malaysian Code on Corporate Governance as revised in 2007 represents the continued collaborative efforts between Government and the industry. Key amendments shown in this Code are aimed at strengthening the board of directors and audit committees, and ensuring that the board of directors and audit committees discharge their roles and responsibilities effectively.', 'The Malaysian Code on Corporate Governance as revised in 2007 represents the continued collaborative efforts between Government and the industry. Key amendments shown in this Code are aimed at strengthening the board of directors and audit committees, and ensuring that the board of directors and audit committees discharge their roles and responsibilities effectively.', 'Malaysia', 'governance', 'in_force', '2007-01-01'::date, 'Malaysia', 'https://www.carrotsandsticks.org/policies/109_12', ARRAY['sdg4', 'malaysia', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3cc9cc50-8156-5f5a-a054-b3ebf54316a1', 'Malaysia Act 514 Occupational Safety and Health Act', 'Act 514 Occupational Safety and Health Act 1994', 'This document outlines an Act to make further provisions for securing the safety, health and welfare of persons at work, for protecting others against risks to safety or health in connection with the activities of persons at work, to establish the National Council for Occupational Safety and Health, and for matters connected therewith.', 'This document outlines an Act to make further provisions for securing the safety, health and welfare of persons at work, for protecting others against risks to safety or health in connection with the activities of persons at work, to establish the National Council for Occupational Safety and Health, and for matters connected therewith.', 'This document outlines an Act to make further provisions for securing the safety, health and welfare of persons at work, for protecting others against risks to safety or health in connection with the activities of persons at work, to establish the National Council for Occupational Safety and Health, and for matters connected therewith.', 'Malaysia', 'social', 'in_force', '1994-01-01'::date, 'Malaysia', 'https://www.carrotsandsticks.org/policies/109_4', ARRAY['sdg8', 'other sustainability policy', 'malaysia', 'regulations', 'mandatory', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bf127b35-15f3-5b5e-a742-911b2104dcea', 'Malta Transparent and Predictable Working Conditions (Amendment) Regulations', 'Transparent and Predictable Working Conditions (Amendment) Regulations, 2025', 'The Transparent and Predictable Working Conditions (Amendment) Regulations, 2025 in Malta aim to enhance transparency in pay levels for job applicants and workers. It requires employers to disclose pay information before and during employment, benefiting applicants and workers seeking clarity on compensation.', 'The Transparent and Predictable Working Conditions (Amendment) Regulations, 2025 in Malta aim to enhance transparency in pay levels for job applicants and workers. It requires employers to disclose pay information before and during employment, benefiting applicants and workers seeking clarity on compensation.', 'The Transparent and Predictable Working Conditions (Amendment) Regulations, 2025 in Malta aim to enhance transparency in pay levels for job applicants and workers. It requires employers to disclose pay information before and during employment, benefiting applicants and workers seeking clarity on compensation.', 'Malta', 'social', 'in_force', '2025-01-01'::date, 'Malta', 'https://www.carrotsandsticks.org/policies/112_6', ARRAY['sdg8', 'regulations', 'mandatory', 'malta', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5005753b-0055-5f34-b3d3-aa34ab649e0c', 'Malta L.N. 32 of 2024 European Union Global Minimum', 'L.N. 32 of 2024 European Union Global Minimum Level of Taxation for Multinational Enterprise Groups and Large-Scale Domestic Groups Regulations, 2024', 'The document outlines Malta''s implementation of EU regulations establishing a global minimum level of taxation for multinational and large-scale domestic groups. It specifies applicability, exemptions, and financial thresholds for entities falling under these regulations, aiming to ensure fair taxation within the European Union. Target audience: multinational and large domestic enterprise groups in Malta.', 'The document outlines Malta''s implementation of EU regulations establishing a global minimum level of taxation for multinational and large-scale domestic groups. It specifies applicability, exemptions, and financial thresholds for entities falling under these regulations, aiming to ensure fair taxation within the European Union. Target audience: multinational and large domestic enterprise groups in Malta.', 'The document outlines Malta''s implementation of EU regulations establishing a global minimum level of taxation for multinational and large-scale domestic groups. It specifies applicability, exemptions, and financial thresholds for entities falling under these regulations, aiming to ensure fair taxation within the European Union. Target audience: multinational and large domestic enterprise groups in Malta.', 'Malta', 'governance', 'in_force', '2024-01-01'::date, 'Malta', 'https://www.carrotsandsticks.org/policies/112_7', ARRAY['mandatory', 'malta', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8a462cc7-5784-5dad-890b-21cc2a15c70a', 'Malta ACT to introduce amendments to the Companies Act', 'An ACT to introduce amendments to the Companies Act and to other Laws and to implement Directive 2014/95/EU.', 'The Maltese Parliament passed an Act in 2016 to introduce amendments to the Companies Act and other laws, in order to implement Directive 2014/95/EU. The aim of the Act is to improve transparency and disclosure by requiring certain large companies to disclose non-financial information related to environmental, social and governance (ESG) factors in their management report. The Act applies to companies with more than 500 employees or those that meet certain turnover and balance sheet thresholds. The ESG information that companies are required to disclose includes information on their business model, policies and outcomes, risks and key performance indicators relating to environmental, social and employee matters, human rights, anti-corruption and bribery issues, and diversity on the company''s board. The Act also requires companies to describe their due diligence processes in relation to these issues. Companies that fail to comply with the Act''s requirements may face fines and other penalties.', 'The Maltese Parliament passed an Act in 2016 to introduce amendments to the Companies Act and other laws, in order to implement Directive 2014/95/EU. The aim of the Act is to improve transparency and disclosure by requiring certain large companies to disclose non-financial information related to environmental, social and governance (ESG) factors in their management report. The Act applies to companies with more than 500 employees or those that meet certain turnover and balance sheet thresholds. The ESG information that companies are required to disclose includes information on their business model, policies and outcomes, risks and key performance indicators relating to environmental, social and employee matters, human rights, anti-corruption and bribery issues, and diversity on the company''s board. The Act also requires companies to describe their due diligence processes in relation to these issues. Companies that fail to comply with the Act''s requirements may face fines and other penalties.', 'The Maltese Parliament passed an Act in 2016 to introduce amendments to the Companies Act and other laws, in order to implement Directive 2014/95/EU. The aim of the Act is to improve transparency and disclosure by requiring certain large companies to disclose non-financial information related to environmental, social and governance (ESG) factors in their management report. The Act applies to companies with more than 500 employees or those that meet certain turnover and balance sheet thresholds. The ESG information that companies are required to disclose includes information on their business model, policies and outcomes, risks and key performance indicators relating to environmental, social and employee matters, human rights, anti-corruption and bribery issues, and diversity on the company''s board. The Act also requires companies to describe their due diligence processes in relation to these issues. Companies that fail to comply with the Act''s requirements may face fines and other penalties.', 'Malta', 'climate', 'in_force', '2016-01-01'::date, 'Malta', 'https://www.carrotsandsticks.org/policies/112_5', ARRAY['regulations', 'mandatory', 'malta', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('54a04132-32cc-5261-ab86-138b1be66fc5', 'Malta Principles of Good Corporate Governance for Public Interest', 'Principles of Good Corporate Governance for Public Interest Companies', 'The aim of these guidelines is to assist enterprises in conducting relations between shareholders, boards of directors and managers.', 'The aim of these guidelines is to assist enterprises in conducting relations between shareholders, boards of directors and managers.', 'The aim of these guidelines is to assist enterprises in conducting relations between shareholders, boards of directors and managers.', 'Malta', 'governance', 'in_force', '2005-01-01'::date, 'Malta', 'https://www.mfsa.mt/wp-content/uploads/2018/12/MFSA-CG-Guidelines-for-Public-Interest.pdf', ARRAY['guidance_frameworks', 'other sustainability policy', 'malta', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c6b39b1a-dc95-5067-a463-41c2a6a3b39f', 'Malta Code of Principles of Good Corporate Governance', 'Code of Principles of Good Corporate Governance', 'These guidelines are designed to enhance the legal, institutional and regulatory framework for good governance in the Maltese corporate sector. They thus complement the current provisions already in force in the Companies Act.', 'These guidelines are designed to enhance the legal, institutional and regulatory framework for good governance in the Maltese corporate sector. They thus complement the current provisions already in force in the Companies Act.', 'These guidelines are designed to enhance the legal, institutional and regulatory framework for good governance in the Maltese corporate sector. They thus complement the current provisions already in force in the Companies Act.', 'Malta', 'governance', 'in_force', '2005-01-01'::date, 'Malta', 'https://www.ecgi.global/sites/default/files/codes/documents/cg_principles_malta_lc_nov2005_en.pdf', ARRAY['guidance_frameworks', 'other sustainability policy', 'malta', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('de8b549d-12a9-54ff-b39f-d0a7fbaa6fa3', 'Mauritius CSR Guide', 'CSR Guide', 'The purpose of this guide is to assist all those corporate concerned bodies in remitting the correct CSR amount at the appropriate time and clarify the areas where CSR money can be used.', 'The purpose of this guide is to assist all those corporate concerned bodies in remitting the correct CSR amount at the appropriate time and clarify the areas where CSR money can be used.', 'The purpose of this guide is to assist all those corporate concerned bodies in remitting the correct CSR amount at the appropriate time and clarify the areas where CSR money can be used.', 'Mauritius', 'governance', 'in_force', '2023-01-01'::date, 'Mauritius', 'https://www.mra.mu/download/CSRGuide.pdf', ARRAY['mandatory', 'mauritius', 'mandatory_regulations', 'other sustainability policy']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3a305176-40e1-5112-9272-58e1cbe5627a', 'National Code of Corporate Governance for Mauritius', 'The National Code of Corporate Governance for Mauritius, 2016', 'This Code comprises a set of principles and guidance aimed at improving and guiding the governance practices of organisations within Mauritius.', 'This Code comprises a set of principles and guidance aimed at improving and guiding the governance practices of organisations within Mauritius.', 'This Code comprises a set of principles and guidance aimed at improving and guiding the governance practices of organisations within Mauritius.', 'Mauritius', 'governance', 'in_force', '2016-01-01'::date, 'Mauritius', 'https://www.carrotsandsticks.org/policies/115_1', ARRAY['mauritius', 'other sustainability policy', 'regulations', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b64c9e50-cccd-5bf6-a8c0-e2108c4df1ad', 'Mauritius Corporate Governance', 'Guideline on Corporate Governance, 2012', 'This guideline broadly sets out the minimum standard of corporate governance that the Bank expects from financial institutions. It covers a variety of governance related issues to guide the actions of the directors and senior officers of financial institutions.', 'This guideline broadly sets out the minimum standard of corporate governance that the Bank expects from financial institutions. It covers a variety of governance related issues to guide the actions of the directors and senior officers of financial institutions.', 'This guideline broadly sets out the minimum standard of corporate governance that the Bank expects from financial institutions. It covers a variety of governance related issues to guide the actions of the directors and senior officers of financial institutions.', 'Mauritius', 'governance', 'in_force', '2012-01-01'::date, 'Mauritius', 'https://www.bom.mu/sites/default/files/pdf/Communique/Guideline_20120803.pdf', ARRAY['guidance_frameworks', 'mauritius', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('73d1936d-ba61-52cd-b6a7-94dc6d8dfefb', 'Report on Corporate Governance For Mauritius', 'The Report on Corporate Governance For Mauritius, 2003', 'This Report reflects on the Code of Corporate Governance in Mauritius. It is relevant and appropriate to to current circumstances in Mauritius but is not and end itself but part of a process that will bring inevitable change in our corporate governance thinking and practices. The Report should therefore be seen as a living document which will evolve over time.', 'This Report reflects on the Code of Corporate Governance in Mauritius. It is relevant and appropriate to to current circumstances in Mauritius but is not and end itself but part of a process that will bring inevitable change in our corporate governance thinking and practices. The Report should therefore be seen as a living document which will evolve over time.', 'This Report reflects on the Code of Corporate Governance in Mauritius. It is relevant and appropriate to to current circumstances in Mauritius but is not and end itself but part of a process that will bring inevitable change in our corporate governance thinking and practices. The Report should therefore be seen as a living document which will evolve over time.', 'Mauritius', 'climate', 'in_force', '2003-01-01'::date, 'Mauritius', 'https://frc.govmu.org/frc/wp-content/uploads/2020/10/report_corporate_governance.pdf', ARRAY['mauritius', 'other sustainability policy', 'mandatory', 'sdg16', 'mandatory_regulations', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('60cf5603-1825-54d4-af4b-600314f961fa', 'Mauritius Income Tax Act 1995 (ITA)', 'Income Tax Act 1995 (ITA).', 'Mauritius'' Income Tax Act 1995 (ITA) lays the foundation for the country''s tax system, outlining taxable income for individuals and companies. It sets different tax rates for diverse income categories, offers deductions for specific expenses, and provides various incentives for businesses operating in the island nation. Regularly updated, the ITA remains a dynamic framework shaping Mauritius'' financial landscape.', 'Mauritius'' Income Tax Act 1995 (ITA) lays the foundation for the country''s tax system, outlining taxable income for individuals and companies. It sets different tax rates for diverse income categories, offers deductions for specific expenses, and provides various incentives for businesses operating in the island nation. Regularly updated, the ITA remains a dynamic framework shaping Mauritius'' financial landscape.', 'Mauritius'' Income Tax Act 1995 (ITA) lays the foundation for the country''s tax system, outlining taxable income for individuals and companies. It sets different tax rates for diverse income categories, offers deductions for specific expenses, and provides various incentives for businesses operating in the island nation. Regularly updated, the ITA remains a dynamic framework shaping Mauritius'' financial landscape.', 'Mauritius', 'nature', 'in_force', '1995-01-01'::date, 'Mauritius', 'https://www.mra.mu/download/ITAConsolidated.pdf', ARRAY['mauritius', 'other sustainability policy', 'regulations', 'mandatory', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b836a2cc-ac58-5535-abbc-63237b5ae1d2', 'Mercosur''s Strategic Social Action Plan', 'Mercosur''s Strategic Social Action Plan', 'This document outlines the Strategic Action Plan of the Social Action which is a fundamental instrument for the artisan development and specification of specific, integral and intersectoral actions, consolidating the Social Dimension of MERCOSUR.', 'This document outlines the Strategic Action Plan of the Social Action which is a fundamental instrument for the artisan development and specification of specific, integral and intersectoral actions, consolidating the Social Dimension of MERCOSUR.', 'This document outlines the Strategic Action Plan of the Social Action which is a fundamental instrument for the artisan development and specification of specific, integral and intersectoral actions, consolidating the Social Dimension of MERCOSUR.', 'Mercosur', 'governance', 'in_force', '2011-01-01'::date, 'SciELO Brazil', 'https://www.scielo.br/j/rk/a/jTSJdMTdSsmMt97xxmtScXG/', ARRAY['mercosur', 'voluntary', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b584a381-601e-5390-80e8-ec6da3d86ec4', 'Mexico sustainable taxonomy', 'Mexico sustainable taxonomy, 2023', 'The Sustainable Taxonomy of Mexico is created with the objective of generating a reliable, legitimate, unified and science-based classification system that allows defining which economic activities can be considered sustainable. With this, the aim is to increase investment in projects and economic activities that promote compliance with the country''s environmental and social objectives, as well as Mexico''s international commitments in terms of sustainability. The Taxonomy will also facilitate access to timely and reliable information to encourage the mobilization of capital towards sustainable activities and reduce the risk of greenwashing.', 'The Sustainable Taxonomy of Mexico is created with the objective of generating a reliable, legitimate, unified and science-based classification system that allows defining which economic activities can be considered sustainable. With this, the aim is to increase investment in projects and economic activities that promote compliance with the country''s environmental and social objectives, as well as Mexico''s international commitments in terms of sustainability. The Taxonomy will also facilitate access to timely and reliable information to encourage the mobilization of capital towards sustainable activities and reduce the risk of greenwashing.', 'The Sustainable Taxonomy of Mexico is created with the objective of generating a reliable, legitimate, unified and science-based classification system that allows defining which economic activities can be considered sustainable. With this, the aim is to increase investment in projects and economic activities that promote compliance with the country''s environmental and social objectives, as well as Mexico''s international commitments in terms of sustainability. The Taxonomy will also facilitate access to timely and reliable information to encourage the mobilization of capital towards sustainable activities and reduce the risk of greenwashing.', 'Mexico', 'climate', 'in_force', '2023-01-01'::date, 'Mexico', 'https://www.carrotsandsticks.org/policies/116_30', ARRAY['sdg13', 'mandatory', 'sdg16', 'mexico', 'mandatory_regulations', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
