INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6122a579-975d-5c2d-99ac-da0f9b4ea5b5', 'Mexico Code of Principles and Best Practices of Corporate', 'Code of Principles and Best Practices of Corporate Governance 2018', 'This is the 2018 version of the Code of Principles and Best Practices of Corporate Governance in Mexico. The principles of the Code are related to the contents of the Code of Business Integrity and Ethics also published by the Business Coordinating Council.', 'This is the 2018 version of the Code of Principles and Best Practices of Corporate Governance in Mexico. The principles of the Code are related to the contents of the Code of Business Integrity and Ethics also published by the Business Coordinating Council.', 'This is the 2018 version of the Code of Principles and Best Practices of Corporate Governance in Mexico. The principles of the Code are related to the contents of the Code of Business Integrity and Ethics also published by the Business Coordinating Council.', 'Mexico', 'governance', 'in_force', '2018-01-01'::date, 'Mexico', 'https://www.ecgi.global/sites/default/files/codes/documents/mexico_code_en.pdf', ARRAY['other sustainability policy', 'regulations', 'sdg16', 'mexico', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e7ec6991-591c-5d2a-b657-33e39a9dd1f3', 'Mexico Code of Principles and Best Practices of Corporate', 'Code of Principles and Best Practices of Corporate Governance', 'This third revised version, has updated the Principles and revised the Best Practices derived from them. To properly reflect its content, the name of the Code has been changed to: “Code of Principles and Best Practices of Corporate Governance”; For reasons of precision, the term strategic vision has been changed to strategic course; the Principle of Honest and Responsible Driving of society has been included; A Best Practice is considered for: i) the prevention and resolution of disputes between shareholders and/or directors; ii) recommend the incorporation of women in the composition of the Board of Directors; iii) the selection, hiring, evaluation and compensation of directors; iv) the elaboration of a Family Agreement for their representation in the governing bodies.', 'This third revised version, has updated the Principles and revised the Best Practices derived from them. To properly reflect its content, the name of the Code has been changed to: “Code of Principles and Best Practices of Corporate Governance”; For reasons of precision, the term strategic vision has been changed to strategic course; the Principle of Honest and Responsible Driving of society has been included; A Best Practice is considered for: i) the prevention and resolution of disputes between shareholders and/or directors; ii) recommend the incorporation of women in the composition of the Board of Directors; iii) the selection, hiring, evaluation and compensation of directors; iv) the elaboration of a Family Agreement for their representation in the governing bodies.', 'This third revised version, has updated the Principles and revised the Best Practices derived from them. To properly reflect its content, the name of the Code has been changed to: “Code of Principles and Best Practices of Corporate Governance”; For reasons of precision, the term strategic vision has been changed to strategic course; the Principle of Honest and Responsible Driving of society has been included; A Best Practice is considered for: i) the prevention and resolution of disputes between shareholders and/or directors; ii) recommend the incorporation of women in the composition of the Board of Directors; iii) the selection, hiring, evaluation and compensation of directors; iv) the elaboration of a Family Agreement for their representation in the governing bodies.', 'Mexico', 'social', 'in_force', '2018-01-01'::date, 'Mexico', 'https://www.ecgi.global/sites/default/files/codes/documents/mexico_code_en.pdf', ARRAY['regulations', 'sdg5', 'sdg16', 'mexico', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('836f6749-e6cc-56ca-b7d6-f9fbffb45d0f', 'Mexico General Climate Change Law', 'General Climate Change Law', 'This law aims to: I. Guarantee the right to a healthy environment and establish the concurrence of faculties of the federation, the states and the municipalities in the elaboration and application of public policies for the adaptation to climate change and the mitigation of emissions of gases and compounds of greenhouse effect; II. Regulate the emissions of gases and greenhouse effect compounds to achieve the stabilization of their concentrations in the atmosphere at a level that prevents dangerous anthropogenic interference in the climate system, considering, where appropriate, the provisions of article 2. of the United Nations Framework Convention on Climate Change and other provisions derived from it; III. Regulate actions for mitigation and adaptation to climate change; IV. Reduce the vulnerability of the country''s population and ecosystems to the adverse effects of climate change, as well as creating and strengthening national capacities to respond to the phenomenon; V. Promote education, research, development and transfer of technology and innovation and dissemination on adaptation and mitigation to climate change; VI. Establish the bases for agreement with society, and VII. Promote the transition to a competitive, sustainable and low-carbon economy.', 'This law aims to: I. Guarantee the right to a healthy environment and establish the concurrence of faculties of the federation, the states and the municipalities in the elaboration and application of public policies for the adaptation to climate change and the mitigation of emissions of gases and compounds of greenhouse effect; II. Regulate the emissions of gases and greenhouse effect compounds to achieve the stabilization of their concentrations in the atmosphere at a level that prevents dangerous anthropogenic interference in the climate system, considering, where appropriate, the provisions of article 2. of the United Nations Framework Convention on Climate Change and other provisions derived from it; III. Regulate actions for mitigation and adaptation to climate change; IV. Reduce the vulnerability of the country''s population and ecosystems to the adverse effects of climate change, as well as creating and strengthening national capacities to respond to the phenomenon; V. Promote education, research, development and transfer of technology and innovation and dissemination on adaptation and mitigation to climate change; VI. Establish the bases for agreement with society, and VII. Promote the transition to a competitive, sustainable and low-carbon economy.', 'This law aims to: I. Guarantee the right to a healthy environment and establish the concurrence of faculties of the federation, the states and the municipalities in the elaboration and application of public policies for the adaptation to climate change and the mitigation of emissions of gases and compounds of greenhouse effect; II. Regulate the emissions of gases and greenhouse effect compounds to achieve the stabilization of their concentrations in the atmosphere at a level that prevents dangerous anthropogenic interference in the climate system, considering, where appropriate, the provisions of article 2. of the United Nations Framework Convention on Climate Change and other provisions derived from it; III. Regulate actions for mitigation and adaptation to climate change; IV. Reduce the vulnerability of the country''s population and ecosystems to the adverse effects of climate change, as well as creating and strengthening national capacities to respond to the phenomenon; V. Promote education, research, development and transfer of technology and innovation and dissemination on adaptation and mitigation to climate change; VI. Establish the bases for agreement with society, and VII. Promote the transition to a competitive, sustainable and low-carbon economy.', 'Mexico', 'climate', 'in_force', '2016-01-01'::date, 'Mexico', 'https://iea.blob.core.windows.net/assets/imports/events/13/GeneralClimateChangeLaw_Englishversion.pdf', ARRAY['sdg4', 'sdg13', 'other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'mexico', 'sdg15', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f91a8bef-562c-5059-999f-0e1b4298d714', 'Mexico General Law of Ecological Balance and Environmental Protection', 'General Law of Ecological Balance and Environmental Protection', 'This Law regulates the provisions of the Political Constitution of the United Mexican States that refer to the preservation and restoration of the ecological balance, as well as the protection of the environment, in the national territory and the areas on which that the nation exercises its sovereignty and jurisdiction. Its provisions are of public order and social interest and are intended to promote sustainable development.', 'This Law regulates the provisions of the Political Constitution of the United Mexican States that refer to the preservation and restoration of the ecological balance, as well as the protection of the environment, in the national territory and the areas on which that the nation exercises its sovereignty and jurisdiction. Its provisions are of public order and social interest and are intended to promote sustainable development.', 'This Law regulates the provisions of the Political Constitution of the United Mexican States that refer to the preservation and restoration of the ecological balance, as well as the protection of the environment, in the national territory and the areas on which that the nation exercises its sovereignty and jurisdiction. Its provisions are of public order and social interest and are intended to promote sustainable development.', 'Mexico', 'climate', 'in_force', '2016-01-01'::date, 'Mexico', 'https://www.carrotsandsticks.org/policies/116_22', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'mexico', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
