INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('70687911-f640-5876-a86f-26a10ab4725a', 'Mexico General Wildlife Law', 'General Wildlife Law', 'This Law is of public order and social interest, regulatory of the third paragraph of article 27 and section XXIX, item G of constitutional article 73. Its purpose is to establish the concurrence of the Federal Government, the governments of the States and the Municipalities, within the scope of their respective competences, regarding the conservation and sustainable use of wildlife and its habitat in the territory of the Mexican Republic. and in the areas where the Nation exercises its jurisdiction.', 'This Law is of public order and social interest, regulatory of the third paragraph of article 27 and section XXIX, item G of constitutional article 73. Its purpose is to establish the concurrence of the Federal Government, the governments of the States and the Municipalities, within the scope of their respective competences, regarding the conservation and sustainable use of wildlife and its habitat in the territory of the Mexican Republic. and in the areas where the Nation exercises its jurisdiction.', 'This Law is of public order and social interest, regulatory of the third paragraph of article 27 and section XXIX, item G of constitutional article 73. Its purpose is to establish the concurrence of the Federal Government, the governments of the States and the Municipalities, within the scope of their respective competences, regarding the conservation and sustainable use of wildlife and its habitat in the territory of the Mexican Republic. and in the areas where the Nation exercises its jurisdiction.', 'Mexico', 'nature', 'in_force', '2015-01-01'::date, 'Mexico', 'https://www.carrotsandsticks.org/policies/116_19', ARRAY['regulations', 'sdg11', 'mandatory', 'mexico', 'disclosure', 'sdg15']::text[]) ON CONFL