INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('46f8053c-54d5-5238-947d-ccaea3f3260d', 'Mexico Regulation of the general law of ecological balance', 'Regulation of the general law of ecological balance and protection of the environment in terms of environmental impact assessment', 'This ordinance is of general observance throughout the national territory and in the areas where the Nation exercises its jurisdiction. Its purpose is to regulate the General Law of Ecological Balance and Environmental Protection, in terms of environmental impact assessment at the federal level.', 'This ordinance is of general observance throughout the national territory and in the areas where the Nation exercises its jurisdiction. Its purpose is to regulate the General Law of Ecological Balance and Environmental Protection, in terms of environmental impact assessment at the federal level.', 'This ordinance is of general observance throughout the national territory and in the areas where the Nation exercises its jurisdiction. Its purpose is to regulate the General Law of Ecological Balance and Environmental Protection, in terms of environmental impact assessment at the federal level.', 'Mexico', 'governance', 'in_force', '2014-01-01'::date, 'Mexico', 'https://www.carrotsandsticks.org/policies/116_15', ARRAY['mandatory', 'mexico', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2db661f2-0fa5-5f3b-9d55-a43b529d417b', 'Mexico Single Environmental License', 'Single Environmental License', 'In 2013, the Mexican government introduced the "Licencia Ambiental Unica" or Single Environmental License, which is a streamlined environmental permit system for businesses operating in Mexico. The license consolidates various environmental permits and authorizations into a single permit, simplifying the process and reducing the regulatory burden for businesses. The license also includes provisions for environmental impact assessments and requires businesses to develop environmental management plans. The aim of the Licencia Ambiental Unica is to improve environmental protection and reduce administrative costs for businesses. By simplifying the regulatory process, the license is expected to promote economic development while also ensuring that businesses operate in an environmentally sustainable manner.', 'In 2013, the Mexican government introduced the "Licencia Ambiental Unica" or Single Environmental License, which is a streamlined environmental permit system for businesses operating in Mexico. The license consolidates various environmental permits and authorizations into a single permit, simplifying the process and reducing the regulatory burden for businesses. The license also includes provisions for environmental impact assessments and requires businesses to develop environmental management plans. The aim of the Licencia Ambiental Unica is to improve environmental protection and reduce administrative costs for businesses. By simplifying the regulatory process, the license is expected to promote economic development while also ensuring that businesses operate in an environmentally sustainable manner.', 'In 2013, the Mexican government introduced the "Licencia Ambiental Unica" or Single Environmental License, which is a streamlined environmental permit system for businesses operating in Mexico. The license consolidates various environmental permits and authorizations into a single permit, simplifying the process and reducing the regulatory burden for businesses. The license also includes provisions for environmental impact assessments and requires businesses to develop environmental management plans. The aim of the Licencia Ambiental Unica is to improve environmental protection and reduce administrative costs for businesses. By simplifying the regulatory process, the license is expected to promote economic development while also ensuring that businesses operate in an environmentally sustainable manner.', 'Mexico', 'climate', 'in_force', '2013-01-01'::date, 'Mexico', 'https://www.carrotsandsticks.org/policies/116_11', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'mexico', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cf51c197-7a94-5ce1-9d33-9895aab97914', 'Mexico Federal Anti-Corruption Law in Public Contracting', 'Federal Anti-Corruption Law in Public Contracting', 'This Law is of public order and general interest and its purpose is: I. Establish the responsibilities and sanctions that must be imposed on natural and legal persons, of Mexican and foreign nationality, for the infractions incurred by reason of their participation in federal public contracting provided for in this Law, as well as those that must be imposed on natural and legal persons of Mexican nationality, for the infractions incurred in the international commercial transactions provided for in this Law, and II. Regulate the procedure to determine responsibilities and apply sanctions, and III. Establish the competent federal authorities to interpret and apply this Law.', 'This Law is of public order and general interest and its purpose is: I. Establish the responsibilities and sanctions that must be imposed on natural and legal persons, of Mexican and foreign nationality, for the infractions incurred by reason of their participation in federal public contracting provided for in this Law, as well as those that must be imposed on natural and legal persons of Mexican nationality, for the infractions incurred in the international commercial transactions provided for in this Law, and II. Regulate the procedure to determine responsibilities and apply sanctions, and III. Establish the competent federal authorities to interpret and apply this Law.', 'This Law is of public order and general interest and its purpose is: I. Establish the responsibilities and sanctions that must be imposed on natural and legal persons, of Mexican and foreign nationality, for the infractions incurred by reason of their participation in federal public contracting provided for in this Law, as well as those that must be imposed on natural and legal persons of Mexican nationality, for the infractions incurred in the international commercial transactions provided for in this Law, and II. Regulate the procedure to determine responsibilities and apply sanctions, and III. Establish the competent federal authorities to interpret and apply this Law.', 'Mexico', 'governance', 'in_force', '2012-01-01'::date, 'Mexico', 'https://nye.com.mx/nye-english/pdf/Mexican-Public-Procurement-Anti-Corruption-Law-2019.pdf', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'mexico']::text[]) ON CONFLICT (id) DO NOTHING;
