INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3bff24f1-ba4b-5d00-98aa-d3fc35e6ad7e', 'Mexico elaboration of the program for the prevention of', 'Guidelines for the elaboration of the program for the prevention of accidents.', 'This document includes guidelines for the development of the program for the prevention of accidents. This guide should not be considered as a questionnaire, so each of the points that integrate it, must be developed with sufficient technical depth, capable of sustaining the comprehensive evaluation of the installation. The information must be presented in Spanish.', 'This document includes guidelines for the development of the program for the prevention of accidents. This guide should not be considered as a questionnaire, so each of the points that integrate it, must be developed with sufficient technical depth, capable of sustaining the comprehensive evaluation of the installation. The information must be presented in Spanish.', 'This document includes guidelines for the development of the program for the prevention of accidents. This guide should not be considered as a questionnaire, so each of the points that integrate it, must be developed with sufficient technical depth, capable of sustaining the comprehensive evaluation of the installation. The information must be presented in Spanish.', 'Mexico', 'governance', 'in_force', '2010-01-01'::date, 'Mexico', 'https://www.carrotsandsticks.org/policies/116_20', ARRAY['guidance_frameworks', 'mexico', 'voluntary', 'other sustainability policy']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('875aad70-2e50-5d1c-8e21-ab892b671988', 'Mexico Code of Best Corporate Practices', 'Code of Best Corporate Practices', 'This Code contains principles that lead to best corporate practices that seek to help companies in their institutionalization process, in the transparency of their operations, in an adequate disclosure of information, to be competitive in a global world, to to be able to access financing sources under favorable conditions, to have stable succession processes and to be permanent over time, for the benefit of its shareholders and interested third parties.', 'This Code contains principles that lead to best corporate practices that seek to help companies in their institutionalization process, in the transparency of their operations, in an adequate disclosure of information, to be competitive in a global world, to to be able to access financing sources under favorable conditions, to have stable succession processes and to be permanent over time, for the benefit of its shareholders and interested third parties.', 'This Code contains principles that lead to best corporate practices that seek to help companies in their institutionalization process, in the transparency of their operations, in an adequate disclosure of information, to be competitive in a global world, to to be able to access financing sources under favorable conditions, to have stable succession processes and to be permanent over time, for the benefit of its shareholders and interested third parties.', 'Mexico', 'governance', 'in_force', '2010-01-01'::date, 'Mexico', 'https://www.ecgi.global/sites/default/files/codes/documents/mexico_code_en.pdf', ARRAY['regulations', 'mandatory', 'sdg16', 'mexico', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f2ac3bc8-bce7-5cac-8357-3fd59db53165', 'Mexico General Law of Commercial Companies', 'General Law of Commercial Companies', '"Ley General de Sociedades Mercantiles" is a comprehensive legal framework for the formation, operation, and governance of commercial entities in the country. The law applies to all types of commercial entities, including corporations, limited liability companies, and partnerships, and establishes guidelines for their organization and operation. The law covers a wide range of topics, including the rights and responsibilities of shareholders and directors, the formation and registration of commercial entities, and the dissolution and liquidation of commercial entities. It also establishes rules for financial reporting and disclosure, as well as for shareholder meetings and decision-making processes. The aim of the law is to promote transparency, accountability, and good governance in commercial entities operating in Mexico, and to provide a clear and predictable legal framework for their operation.', '"Ley General de Sociedades Mercantiles" is a comprehensive legal framework for the formation, operation, and governance of commercial entities in the country. The law applies to all types of commercial entities, including corporations, limited liability companies, and partnerships, and establishes guidelines for their organization and operation. The law covers a wide range of topics, including the rights and responsibilities of shareholders and directors, the formation and registration of commercial entities, and the dissolution and liquidation of commercial entities. It also establishes rules for financial reporting and disclosure, as well as for shareholder meetings and decision-making processes. The aim of the law is to promote transparency, accountability, and good governance in commercial entities operating in Mexico, and to provide a clear and predictable legal framework for their operation.', '"Ley General de Sociedades Mercantiles" is a comprehensive legal framework for the formation, operation, and governance of commercial entities in the country. The law applies to all types of commercial entities, including corporations, limited liability companies, and partnerships, and establishes guidelines for their organization and operation. The law covers a wide range of topics, including the rights and responsibilities of shareholders and directors, the formation and registration of commercial entities, and the dissolution and liquidation of commercial entities. It also establishes rules for financial reporting and disclosure, as well as for shareholder meetings and decision-making processes. The aim of the law is to promote transparency, accountability, and good governance in commercial entities operating in Mexico, and to provide a clear and predictable legal framework for their operation.', 'Mexico', 'climate', 'in_force', '2009-01-01'::date, 'Mexico', 'https://webfiles-sc1.blackbaud.com/files/support/helpfiles/npoconnect/content/resources/attachments/mexico-1934-general-law-of-commercial-companies.pdf', ARRAY['other sustainability policy', 'regulations', 'sdg17', 'mandatory', 'sdg16', 'mexico']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('20030ea9-9057-5218-8598-aed721147c56', 'Mexico Guide for the Presentation of the Preventive Report', 'Guide for the Presentation of the Preventive Report', 'This is a guide to the law that regulates the provisions of the Political Constitution of the United Mexican States that refer to the preservation and restoration of the ecological balance, as well as the protection of the environment, in the national territory and the areas on which that the nation exercises its sovereignty and jurisdiction. Its provisions are of public order and social interest and are intended to promote sustainable development.', 'This is a guide to the law that regulates the provisions of the Political Constitution of the United Mexican States that refer to the preservation and restoration of the ecological balance, as well as the protection of the environment, in the national territory and the areas on which that the nation exercises its sovereignty and jurisdiction. Its provisions are of public order and social interest and are intended to promote sustainable development.', 'This is a guide to the law that regulates the provisions of the Political Constitution of the United Mexican States that refer to the preservation and restoration of the ecological balance, as well as the protection of the environment, in the national territory and the areas on which that the nation exercises its sovereignty and jurisdiction. Its provisions are of public order and social interest and are intended to promote sustainable development.', 'Mexico', 'climate', 'in_force', '2005-01-01'::date, 'Mexico', 'https://www.carrotsandsticks.org/policies/116_17', ARRAY['sdg13', 'other sustainability policy', 'mandatory', 'sdg16', 'mexico', 'mandatory_regulations', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2edab7ad-bbcc-5183-93aa-2cdccbc865ea', 'Corporate Governance Code for Mexico', 'Corporate Governance Code for Mexico', 'The document was prepared jointly by the Mexican Stock Exchange, the Mexican Bankers'' Association, the Mexican Institute of Finance Executives and the Mexican Institute of Public Accountants, as well as representatives from the industrial, retail and service sectors. It was then submitted to the National Banking and Securities Commission so that the securities authorities could issue the necessary regulatory provisions on disclosure of information regarding conformity to the practices suggested therein.
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2ea50adf-3c99-5ea0-87de-d63010310c5c', 'Mexico Official Mexican STANDARD NOM-002-ECOL-1996, which establishes the maximum', 'Official Mexican STANDARD NOM-002-ECOL-1996, which establishes the maximum permissible limits of pollutants in wastewater discharges to urban or municipal sewage systems.', 'This document was published in the Official Gazette of the Federation, which establishes the maximum permissible limits of contaminants in wastewater discharges from industry, agro-industrial activities, services and wastewater treatment to urban or municipal drainage and sewage systems.', 'This document was published in the Official Gazette of the Federation, which establishes the maximum permissible limits of contaminants in wastewater discharges from industry, agro-industrial activities, services and wastewater treatment to urban or municipal drainage and sewage systems.', 'This document was published in the Official Gazette of the Federation, which establishes the maximum permissible limits of contaminants in wastewater discharges from industry, agro-industrial activities, services and wastewater treatment to urban or municipal drainage and sewage systems.', 'Mexico', 'nature', 'in_force', '1998-01-01'::date, 'Mexico', 'https://www.profepa.gob.mx/innovaportal/file/3295/1/nom-002-semarnat-1996.pdf', ARRAY['sdg14', 'other sustainability policy', 'sdg11', 'sdg6', 'voluntary', 'mexico', 'sdg12', 'sdg9', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3ae5d6ca-c7fb-5a53-a306-aa16fa356bd4', 'Moldova Law of 22-05-2025 on environmental liability in relation', 'Law No. 107 of 22-05-2025 on environmental liability in relation to  the prevention and remedying of environmental damage', 'Moldova''s Law No. 107 of 2025 establishes environmental liability based on the "polluter pays" principle. It aims to prevent and remedy environmental damage, applying to various activities and habitats. The law does not interfere with existing environmental or property damage recovery laws.', 'Moldova''s Law No. 107 of 2025 establishes environmental liability based on the "polluter pays" principle. It aims to prevent and remedy environmental damage, applying to various activities and habitats. The law does not interfere with existing environmental or property damage recovery laws.', 'Moldova''s Law No. 107 of 2025 establishes environmental liability based on the "polluter pays" principle. It aims to prevent and remedy environmental damage, applying to various activities and habitats. The law does not interfere with existing environmental or property damage recovery laws.', 'Moldova', 'nature', 'in_force', '2025-01-01'::date, 'Moldova', 'https://www.carrotsandsticks.org/policies/118_4', ARRAY['sdg15', 'mandatory', 'moldova', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e12e32dc-2c91-5848-9114-d3a594f6f9ab', 'Moldova Decision on the approval of the Corporate Governance', 'Decision No. 67/10 on the approval of the Corporate Governance Code', 'This Code provides for national and international best practices and represents a set of governance standards for the company''s management and shareholders in applying the efficient management of a company.', 'This Code provides for national and international best practices and represents a set of governance standards for the company''s management and shareholders in applying the efficient management of a company.', 'This Code provides for national and international best practices and represents a set of governance standards for the company''s management and shareholders in applying the efficient management of a company.', 'Moldova', 'governance', 'in_force', '2016-01-01'::date, 'Moldova', 'https://www.maib.md/files/2016/9/26/codul-de-guvernanta-corporativa-al-bc-moldova-agroindbank-s-a-1/codul-de-guvernanta-corporativa-al-bc-moldova-agroindbank-s-a-1.pdf', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'moldova']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5773f5b2-e497-50a3-8361-779ffd80b0e4', 'Moldova Eco-Labelling of the Priority Groups - PVC Sustainable', 'Eco-Labelling of the Priority Groups - PVC Sustainable Windows and Doors and Organic Fruits and Vegetables', 'The aims of the implementation of this sustainable procurement are: development of a market for ecological products and services which would lead to the improvement of environmental performance of services and products, as well as the technologies applied to obtain them; modernization of public institutions from the point of view of products, services and works whose acquisition would include, when possible, ecological criteria in the tender documentation to allow biodiversity conservation, reduction of the excessive use of natural resources, protection and improvement of the environment, prevention and reduction of environmental pollution, promotion of sustainable consumption and production, thus reducing environmental degradation while still promoting economic growth.', 'The aims of the implementation of this sustainable procurement are: development of a market for ecological products and services which would lead to the improvement of environmental performance of services and products, as well as the technologies applied to obtain them; modernization of public institutions from the point of view of products, services and works whose acquisition would include, when possible, ecological criteria in the tender documentation to allow biodiversity conservation, reduction of the excessive use of natural resources, protection and improvement of the environment, prevention and reduction of environmental pollution, promotion of sustainable consumption and production, thus reducing environmental degradation while still promoting economic growth.', 'The aims of the implementation of this sustainable procurement are: development of a market for ecological products and services which would lead to the improvement of environmental performance of services and products, as well as the technologies applied to obtain them; modernization of public institutions from the point of view of products, services and works whose acquisition would include, when possible, ecological criteria in the tender documentation to allow biodiversity conservation, reduction of the excessive use of natural resources, protection and improvement of the environment, prevention and reduction of environmental pollution, promotion of sustainable consumption and production, thus reducing environmental degradation while still promoting economic growth.', 'Moldova', 'nature', 'in_force', '2015-01-01'::date, 'Moldova', 'https://www.carrotsandsticks.org/policies/118_3', ARRAY['other sustainability policy', 'mandatory', 'mandatory_regulations', 'moldova', 'sdg12', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('250a48e6-4722-5ca8-9a6a-ff6ce4b8abd4', 'Moldova Code of Corporate Governance', 'Code of Corporate Governance', 'The Code contains principles and concrete situations, which the implied persons of the company (members of the executive body, Council, supervisory bodies, and the shareholders) should follow in mutual relations.', 'The Code contains principles and concrete situations, which the implied persons of the company (members of the executive body, Council, supervisory bodies, and the shareholders) should follow in mutual relations.', 'The Code contains principles and concrete situations, which the implied persons of the company (members of the executive body, Council, supervisory bodies, and the shareholders) should follow in mutual relations.', 'Moldova', 'governance', 'in_force', '2007-01-01'::date, 'Moldova', 'https://ibn.idsi.md/sites/default/files/imag_file/104-108_53.pdf', ARRAY['guidance_frameworks', 'other sustainability policy', 'mandatory', 'sdg16', 'moldova']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a3964957-f484-568d-9411-fedcbee7b899', 'Monaco Environmental Code (Law .456)', 'Environmental Code (Law no. 1.456)', 'The Environmental Code (Law no. 1.456) of Monaco, established in 2017, focuses on environmental regulations. It addresses issues related to environmental protection, sustainability, and conservation, with specific provisions for compliance and enforcement. This policy is essential for all individuals, organizations, and industries operating in Monaco to ensure environmental responsibility and stewardship.', 'The Environmental Code (Law no. 1.456) of Monaco, established in 2017, focuses on environmental regulations. It addresses issues related to environmental protection, sustainability, and conservation, with specific provisions for compliance and enforcement. This policy is essential for all individuals, organizations, and industries operating in Monaco to ensure environmental responsibility and stewardship.', 'The Environmental Code (Law no. 1.456) of Monaco, established in 2017, focuses on environmental regulations. It addresses issues related to environmental protection, sustainability, and conservation, with specific provisions for compliance and enforcement. This policy is essential for all individuals, organizations, and industries operating in Monaco to ensure environmental responsibility and stewardship.', 'Monaco', 'climate', 'in_force', '2017-01-01'::date, 'Monaco', 'https://www.carrotsandsticks.org/policies/201_1', ARRAY['monaco', 'sdg13', 'regulations', 'mandatory', 'sdg16', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b9b38eea-e7e9-5e11-8aff-ec004d006ccc', 'ESG & Sustainability Reporting Guidance for Mongolian Companies', 'ESG & Sustainability Reporting Guidance for Mongolian Companies', 'While this Guidance is voluntary, it aims to: Raise awareness amongst issuers and investors on the importance of sustainability reporting and help issuers navigate the rapidly evolving landscape of sustainability disclosure; Outline simple steps for companies to help prepare annual sustainability reports; Suggest a set of key ESG indicators that companies should consider reporting on; Provide some practical resources that companies can explore when preparing their sustainability or integrated reports; Assist in contributing to the achievement of national and international sustainable development commitments and priorities, such as the National Development Plan and UN SDGs. The Guidance can be used by both large and small issuers either listed or non-listed as well as organizations that already have a long history of sustainability performance and those that are just starting on the journey. Listed issuers are strongly encouraged to refer to this Guidance in the implementation of sustainability practices, as well as annual reporting. Organizations that are not listed on the stock exchange (e.g., limited liability companies, state owned enterprises, non-governmental organizations) may use this document as a guide to assess their sustainability reporting practices and identify and address any gaps.', 'While this Guidance is voluntary, it aims to: Raise awareness amongst issuers and investors on the importance of sustainability reporting and help issuers navigate the rapidly evolving landscape of sustainability disclosure; Outline simple steps for companies to help prepare annual sustainability reports; Suggest a set of key ESG indicators that companies should consider reporting on; Provide some practical resources that companies can explore when preparing their sustainability or integrated reports; Assist in contributing to the achievement of national and international sustainable development commitments and priorities, such as the National Development Plan and UN SDGs. The Guidance can be used by both large and small issuers either listed or non-listed as well as organizations that already have a long history of sustainability performance and those that are just starting on the journey. Listed issuers are strongly encouraged to refer to this Guidance in the implementation of sustainability practices, as well as annual reporting. Organizations that are not listed on the stock exchange (e.g., limited liability companies, state owned enterprises, non-governmental organizations) may use this document as a guide to assess their sustainability reporting practices and identify and address any gaps.', 'While this Guidance is voluntary, it aims to: Raise awareness amongst issuers and investors on the importance of sustainability reporting and help issuers navigate the rapidly evolving landscape of sustainability disclosure; Outline simple steps for companies to help prepare annual sustainability reports; Suggest a set of key ESG indicators that companies should consider reporting on; Provide some practical resources that companies can explore when preparing their sustainability or integrated reports; Assist in contributing to the achievement of national and international sustainable development commitments and priorities, such as the National Development Plan and UN SDGs. The Guidance can be used by both large and small issuers either listed or non-listed as well as organizations that already have a long history of sustainability performance and those that are just starting on the journey. Listed issuers are strongly encouraged to refer to this Guidance in the implementation of sustainability practices, as well as annual reporting. Organizations that are not listed on the stock exchange (e.g., limited liability companies, state owned enterprises, non-governmental organizations) may use this document as a guide to assess their sustainability reporting practices and identify and address any gaps.', 'Mongolia', 'climate', 'in_force', '2022-01-01'::date, 'Mongolia', 'https://www.undp.org/sites/g/files/zskgke326/files/2022-08/ESG%20reporting%20ENG.pdf', ARRAY['guidance_frameworks', 'mandatory', 'mongolia', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b4ad5590-f559-567a-a77d-4f662c5dae1d', 'Mongolian Textile Sector-Specific Green Loan Criteria Guide', 'Mongolian Textile Sector-Specific Green Loan Criteria Guide, 2021', 'The green loan criteria document defines the basic criteria, verification methods and categories that financial institutions are recommended to apply to issue green loans and evaluate green projects in the Mongolian textile sector.', 'The green loan criteria document defines the basic criteria, verification methods and categories that financial institutions are recommended to apply to issue green loans and evaluate green projects in the Mongolian textile sector.', 'The green loan criteria document defines the basic criteria, verification methods and categories that financial institutions are recommended to apply to issue green loans and evaluate green projects in the Mongolian textile sector.', 'Mongolia', 'climate', 'in_force', '2021-01-01'::date, 'Mongolia', 'https://data.sbfnetwork.org/sites/default/files/1250_Mongolia_Sustainable_Finance_Principles_Textile_Sector_Guideline_2019_MBA.pdf', ARRAY['sdg13', 'mandatory', 'mongolia', 'sdg16', 'mandatory_regulations', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('60debf39-2e26-5cb8-821f-40248ca81d4d', 'Mongolian Sustainable Finance Principles. Textiles sector guideline', 'Mongolian Sustainable Finance Principles. Textiles sector guideline 2019', 'This Guideline for banks providing debt or equity to the Textiles sector or mining activities was developed as a companion document to the Mongolian Sustainable Finance Principles (the Principles). All banks involved in financing mining sector clients, projects or transactions should apply the Mongolian Sustainable Finance Principles and this Sector Guideline when assessing new clients, projects or transactions.', 'This Guideline for banks providing debt or equity to the Textiles sector or mining activities was developed as a companion document to the Mongolian Sustainable Finance Principles (the Principles). All banks involved in financing mining sector clients, projects or transactions should apply the Mongolian Sustainable Finance Principles and this Sector Guideline when assessing new clients, projects or transactions.', 'This Guideline for banks providing debt or equity to the Textiles sector or mining activities was developed as a companion document to the Mongolian Sustainable Finance Principles (the Principles). All banks involved in financing mining sector clients, projects or transactions should apply the Mongolian Sustainable Finance Principles and this Sector Guideline when assessing new clients, projects or transactions.', 'Mongolia', 'climate', 'in_force', '2019-01-01'::date, 'Mongolia', 'https://www.carrotsandsticks.org/policies/120_9', ARRAY['guidance_frameworks', 'sdg13', 'mongolia', 'sdg16', 'sdg12', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('66efdc6b-abda-5dfe-a74b-9c46cf455507', 'Mongolian Green Taxonomy', 'Mongolian Green Taxonomy, 2018', 'The overall objective of the green taxonomy is: “To develop a nationally agreed classification framework of activities that contribute to climate change mitigation, adaptation, pollution prevention, resource conservation, and livelihood improvement in the context of green finance.”', 'The overall objective of the green taxonomy is: “To develop a nationally agreed classification framework of activities that contribute to climate change mitigation, adaptation, pollution prevention, resource conservation, and livelihood improvement in the context of green finance.”', 'The overall objective of the green taxonomy is: “To develop a nationally agreed classification framework of activities that contribute to climate change mitigation, adaptation, pollution prevention, resource conservation, and livelihood improvement in the context of green finance.”', 'Mongolia', 'climate', 'in_force', '2018-01-01'::date, 'Mongolia', 'https://www.carrotsandsticks.org/policies/120_7', ARRAY['sdg13', 'other sustainability policy', 'mandatory', 'mongolia', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3137ec9b-3f37-5149-80ac-8e673d961780', 'Mongolian Sustainable Finance Principles. Manufacturing Sector Guideline', 'Mongolian Sustainable Finance Principles. Manufacturing Sector Guideline', 'This Guideline for banks providing debt or equity to the Manufacturing sector or mining activities was developed as a companion document to the Mongolian Sustainable Finance Principles (the Principles). All banks involved in financing mining sector clients, projects or transactions should apply the Mongolian Sustainable Finance Principles and this Sector Guideline when assessing new clients, projects or transactions.', 'This Guideline for banks providing debt or equity to the Manufacturing sector or mining activities was developed as a companion document to the Mongolian Sustainable Finance Principles (the Principles). All banks involved in financing mining sector clients, projects or transactions should apply the Mongolian Sustainable Finance Principles and this Sector Guideline when assessing new clients, projects or transactions.', 'This Guideline for banks providing debt or equity to the Manufacturing sector or mining activities was developed as a companion document to the Mongolian Sustainable Finance Principles (the Principles). All banks involved in financing mining sector clients, projects or transactions should apply the Mongolian Sustainable Finance Principles and this Sector Guideline when assessing new clients, projects or transactions.', 'Mongolia', 'climate', 'in_force', '2018-01-01'::date, 'Mongolia', 'https://www.carrotsandsticks.org/policies/120_8', ARRAY['regulations', 'mongolia', 'disclosure', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('258c8d36-c561-5fe0-bf25-6896be3ba5f2', 'Mongolian Sustainable Finance Principles Guidelines', 'Mongolian Sustainable Finance Principles Guidelines, 2014', 'The supporting guidance contained in this document is intended to help banks in setting up policies, processes, and decision-making around what we have determined to be the critical issues for sustainable finance in Mongolia.', 'The supporting guidance contained in this document is intended to help banks in setting up policies, processes, and decision-making around what we have determined to be the critical issues for sustainable finance in Mongolia.', 'The supporting guidance contained in this document is intended to help banks in setting up policies, processes, and decision-making around what we have determined to be the critical issues for sustainable finance in Mongolia.', 'Mongolia', 'climate', 'in_force', '2014-01-01'::date, 'Mongolia', 'https://data.sbfnetwork.org/sites/default/files/1330_Mongolia_Sustainable_Finance_Principle_Guidelines_2014_MBA.pdf', ARRAY['guidance_frameworks', 'sdg13', 'other sustainability policy', 'mongolia', 'sdg16', 'sdg12', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2298af98-7c7f-568d-96ef-4a1260301037', 'Mongolian Sustainable Finance Principles. Agriculture Sector Guideline', 'Mongolian Sustainable Finance Principles. Agriculture Sector Guideline', 'This Guideline for banks providing debt or equity to the Agriculture sector or mining activities was developed as a companion document to the Mongolian Sustainable Finance Principles (the Principles). All banks involved in financing mining sector clients, projects or transactions should apply the Mongolian Sustainable Finance Principles and this Sector Guideline when assessing new clients, projects or transactions.', 'This Guideline for banks providing debt or equity to the Agriculture sector or mining activities was developed as a companion document to the Mongolian Sustainable Finance Principles (the Principles). All banks involved in financing mining sector clients, projects or transactions should apply the Mongolian Sustainable Finance Principles and this Sector Guideline when assessing new clients, projects or transactions.', 'This Guideline for banks providing debt or equity to the Agriculture sector or mining activities was developed as a companion document to the Mongolian Sustainable Finance Principles (the Principles). All banks involved in financing mining sector clients, projects or transactions should apply the Mongolian Sustainable Finance Principles and this Sector Guideline when assessing new clients, projects or transactions.', 'Mongolia', 'climate', 'in_force', '2014-01-01'::date, 'Mongolia', 'https://www.carrotsandsticks.org/policies/120_4', ARRAY['guidance_frameworks', 'sdg2', 'mongolia', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
